<?php
namespace App\Services\Football;use App\Models\{Fixture,MarketAnalysis};use App\Services\Analysis\Markets\{TeamOver05Analyser,Under45Analyser,MatchWinnerAnalyser,TeamOrGGAnalyser};final class FixtureAnalysisService{public function __construct(private TeamGoalEvidenceBuilder $teamEvidence,private MatchEvidenceBuilder $matchEvidence,private TeamOver05Analyser $team05,private Under45Analyser $under45,private MatchWinnerAnalyser $winner,private TeamOrGGAnalyser $teamOrGg){}public function analyse(Fixture $fixture):array{$fixture->loadMissing(['homeTeam','awayTeam']);$results=[];foreach([[true,$fixture->homeTeam->name],[false,$fixture->awayTeam->name]] as[$home,$name])$results[]=$this->team05->analyse($name,$this->teamEvidence->build($fixture,$home));$m=$this->matchEvidence->build($fixture);$results[]=$this->under45->analyse($m);array_push($results,...$this->winner->analyse($fixture->homeTeam->name,$fixture->awayTeam->name,$m));array_push($results,...$this->teamOrGg->analyse($fixture->homeTeam->name,$fixture->awayTeam->name,$m));return array_map(fn($r)=>MarketAnalysis::updateOrCreate(['fixture_id'=>$fixture->id,'market_type'=>$r->market->value,'selection'=>$r->selection],['score'=>$r->score,'data_quality_score'=>$r->dataQuality,'status'=>$r->status->value,'positive_signals'=>$r->positiveSignals,'contradictions'=>$r->contradictions,'main_risk'=>$r->mainRisk,'analysed_at'=>now(),'result'=>null,'graded_at'=>null]),$results);}}
